hl.on("hyprland.start", function()
    hl.exec_cmd("waybar")
    hl.exec_cmd("dunst")
    hl.exec_cmd("sleep 2 && /usr/lib/polkit-kde-authentication-agent-1")
    hl.exec_cmd("sleep 2 && nextcloud --background")
    hl.exec_cmd("sleep 2 && wlsunset -l 48.21 -L 16.36")
    hl.exec_cmd("sleep 2 && keepassxc")
    hl.exec_cmd("sleep 2 && blueman-applet")
end)

